Body:
hope this help for anyone reading, this my config for OpenCode via OpenRouter DeepSeek V4 Flash Max Reasoning

```json
{
  "$schema": "https://opencode.ai/config.json",
  "provider": {
    "openrouter": {
      "models": {
        "deepseek/deepseek-v4-flash": {
          "name": "openrouter deepseek v4 flash maxxxxx",
          "options": {
            "reasoning_effort": "xhigh",
            "thinking": {
              "type": "enabled",
            },
            "provider": {
              "order": ["siliconflow/fp8"],
              "allow_fallbacks": false,
              "data_collection": "deny",
            },
          },
        },
      },
    },
  },
  "small_model": "openrouter/openrouter/free",
}


```
